/**
 * Normaliza um evento webhook da WhatsApp Cloud API (Meta) — design.md,
 * Camada de decisão (AGT-01). Extrai só o que o fluxo precisa de um evento
 * `messages`; eventos `statuses` (delivered/read/sent/failed) e qualquer
 * payload sem os campos de identidade mínimos (phone_number_id/wa_id/id da
 * mensagem/timestamp válido) retornam `null` — nunca lança exceção sobre um
 * payload inesperado (reentrega/replay é rotina numa integração de
 * webhook).
 *
 * Função pura, sem I/O, sem dependências — roda dentro de um Code node do
 * n8n (sandbox: sem `require`, sem rede). Mapeamento de `phone_number_id`
 * para tenant e a decisão de descartar números não mapeados (AGT-01 AC4)
 * acontecem DEPOIS desta função, no lookup da Data Table `tenant_config`
 * (design.md — pipeline, passo 4) — esta função é agnóstica a qual tenant
 * o número pertence.
 *
 * Qualquer mensagem que não seja `type: "text"` (imagem, áudio, documento,
 * figurinha, localização, etc.) é tratada como mídia: `hasMedia: true` e
 * `text: ""` sempre — o agente responde com uma mensagem fixa "sigo por
 * texto" sem depender do conteúdo (spec.md — Edge Cases: mídia nunca é
 * persistida nem interpretada, incondicionalmente).
 *
 * @param {unknown} metaPayload - corpo bruto do POST do webhook da Meta
 * @returns {{waId: string, phoneNumberId: string, messageId: string, text: string, sentAt: string, hasMedia: boolean} | null}
 */
function normalizeEvent(metaPayload) {
  const value = metaPayload?.entry?.[0]?.changes?.[0]?.value;
  if (!value || typeof value !== "object") return null;

  // Eventos `statuses` (delivered/read/sent/failed) não são mensagens —
  // descartados sem erro (spec.md — Edge Cases).
  const message = Array.isArray(value.messages) ? value.messages[0] : undefined;
  if (!message || typeof message !== "object") return null;

  const phoneNumberId = value.metadata?.phone_number_id;
  const waId = message.from;
  const messageId = message.id;
  if (
    typeof phoneNumberId !== "string" ||
    phoneNumberId === "" ||
    typeof waId !== "string" ||
    waId === "" ||
    typeof messageId !== "string" ||
    messageId === ""
  ) {
    return null;
  }

  const timestampSeconds = Number(message.timestamp);
  if (!Number.isFinite(timestampSeconds)) return null;
  const sentAt = new Date(timestampSeconds * 1000).toISOString();

  const hasMedia = message.type !== "text";
  const text = hasMedia ? "" : message.text?.body ?? "";

  return { waId, phoneNumberId, messageId, text, sentAt, hasMedia };
}

const metaPayload = ($json && Array.isArray($json.entry))
  ? $json
  : { entry: [{ changes: [{ value: $json }] }] };
const event = normalizeEvent(metaPayload);
if (!event) {
  return null;
}
const value = metaPayload.entry?.[0]?.changes?.[0]?.value ?? {};
const contactName = value.contacts?.[0]?.profile?.name || event.waId;
return { json: { ...event, contactName } };

const event = $('Code: normalizeEvent').item.json;
const tenant = $json;
return { json: {
  waId: event.waId, phoneNumberId: event.phoneNumberId, messageId: event.messageId,
  text: event.text, sentAt: event.sentAt, hasMedia: event.hasMedia, contactName: event.contactName,
  tenantSlug: tenant.tenantSlug, calendarId: tenant.calendarId,
} };

const ctx = $('Code: combinar evento e tenant').item.json;
const existing = $json.bufferJson ? JSON.parse($json.bufferJson) : [];
const bufferArray = [...existing, { messageId: ctx.messageId, text: ctx.text, sentAt: ctx.sentAt }];
return { json: { tenantSlug: ctx.tenantSlug, waId: ctx.waId, messageId: ctx.messageId, bufferArray, bufferJson: JSON.stringify(bufferArray) } };

const myMessageId = $('Code: acrescentar ao buffer').item.json.messageId;
const currentBuffer = $json.bufferJson ? JSON.parse($json.bufferJson) : [];
const newestInBuffer = currentBuffer.length > 0 ? currentBuffer[currentBuffer.length - 1].messageId : null;
return { json: { stillLatest: newestInBuffer === myMessageId } };

const lead = $input.first().json;
const ctx = $('Code: combinar evento e tenant').first().json;
const buffer = $('Code: acrescentar ao buffer').first().json.bufferArray;
return [{ json: { ...lead, tenantSlug: ctx.tenantSlug, calendarId: ctx.calendarId, waId: ctx.waId, phoneNumberId: ctx.phoneNumberId, contactName: ctx.contactName, text: ctx.text, hasMedia: ctx.hasMedia, sentAt: ctx.sentAt, bufferArray: buffer } }];

/**
 * Detecção de opt-out + máquina de estados de roteamento da conversa
 * (design.md — Camada de decisão; LGPD-03, AGT-05 AC3, AGT-01). Funções
 * puras, sem I/O, sem dependências — rodam dentro de um Code node do n8n.
 */

// Faixa Unicode dos diacríticos combinantes (U+0300-U+036F) produzidos pela
// decomposição NFD — escrita como escape \uXXXX (não caractere literal) de
// propósito, para o padrão ficar legível e imune a mangling de encoding.
const DIACRITICS_PATTERN = /[̀-ͯ]/g;
const OPT_OUT_KEYWORDS = new Set(["sair", "parar"]);

/**
 * Remove acentos (via decomposição NFD + descarte dos diacríticos
 * combinantes), apara espaços e normaliza para minúsculas — sem depender de
 * nenhuma lib externa.
 * @param {string} text
 * @returns {string}
 */
function foldAccentsAndCase(text) {
  return text.normalize("NFD").replace(DIACRITICS_PATTERN, "").trim().toLowerCase();
}

/**
 * Detecta opt-out (LGPD-03): a mensagem inteira, depois de normalizada
 * (minúsculas, sem acento, sem espaços nas bordas), precisa ser EXATAMENTE
 * "sair" ou "parar" — a palavra isolada, não uma frase que a contém. Isso é
 * deliberado: "quero sair do apartamento" é uma frase sobre o imóvel, não um
 * comando de descadastro, e não pode disparar opt-out (spec.md — LGPD-03,
 * "Done when").
 * @param {unknown} text
 * @returns {boolean}
 */
function detectOptOut(text) {
  if (typeof text !== "string") return false;
  const normalized = foldAccentsAndCase(text);
  return OPT_OUT_KEYWORDS.has(normalized);
}

/**
 * @typedef {"opt-out" | "somente-registrar" | "midia" | "conversa"} GateRoute
 */

/**
 * Decide a ÚNICA rota de uma mensagem recebida (design.md — Camada de
 * decisão, pipeline passo 7). Precedência, na ordem exata abaixo (cada
 * checagem só é avaliada se as anteriores não decidiram):
 *
 * 1. `optedOutAt` já preenchido (lead opinou por sair numa mensagem
 *    ANTERIOR) vence tudo → 'somente-registrar'. Isso evita reenviar a
 *    confirmação de descadastro (que o contrato exige ser única — LGPD-03
 *    AC1) quando um lead já opted-out manda "sair" de novo, ou qualquer
 *    outra mensagem (LGPD-03 AC3: nunca retoma a conversa automaticamente).
 * 2. Só então o texto é checado: opt-out detectado agora → 'opt-out'
 *    (LGPD-03 AC1 — primeira vez, dispara confirmação única). Vence a
 *    checagem de mídia abaixo (um opt-out em texto nunca é tratado como
 *    mídia).
 * 3. `status === 'escalado_humano'` (humano assumiu) **ou** a marca de
 *    condução humana `humanTakeoverAt` (lote-14, SILENCIO-01 AC2) →
 *    'somente-registrar' (AGT-05 AC3) — vence a checagem de mídia abaixo
 *    também. A palavra exata de opt-out (passo 2) continua vencendo a marca
 *    (SILENCIO-01 AC3).
 * 4. Mídia sem texto (`hasMedia` e nenhum texto) → 'midia' (edge case —
 *    resposta fixa "sigo por texto", sem LLM).
 * 5. Caso contrário → 'conversa' (rota padrão, segue para o LLM).
 *
 * @param {{optedOutAt: unknown, status: unknown, humanTakeoverAt?: unknown, hasMedia: unknown, text: unknown}} input
 * @returns {GateRoute}
 */
function gate({ optedOutAt, status, humanTakeoverAt, hasMedia, text }) {
  if (optedOutAt) return "somente-registrar";
  if (detectOptOut(text)) return "opt-out";
  if (status === "escalado_humano" || humanTakeoverAt) return "somente-registrar";
  if (hasMedia && !text) return "midia";
  return "conversa";
}

const ctx = $('Code: contexto do lead').first().json;
const route = gate({ optedOutAt: ctx.optedOutAt, status: ctx.status, humanTakeoverAt: ctx.humanTakeoverAt, hasMedia: ctx.hasMedia, text: ctx.text });
return [{ json: { ...ctx, route } }];

/**
 * Opt-out em linguagem natural (lote-13 — design.md, módulo
 * `n8n/src/opt-out-intent.mjs`; spec.md OPTMSG-01, OPTREG-01, OPTAMB-01).
 * Funções puras, sem I/O, sem dependências — rodam dentro de um Code node do
 * n8n. Este arquivo inteiro entra na identidade do classificador
 * (`scripts/opt-out-measurement.ts`): mudar qualquer texto daqui exige nova
 * medição aprovada.
 */

/** Confirmação única dos dois caminhos de opt-out (OPTMSG-01 AC1, AC2). */
const OPT_OUT_CONFIRMATION =
  "Pronto, registramos seu pedido. Você não vai mais receber mensagens nossas por este número. Até mais!";

/**
 * Falha do registro por linguagem natural (OPTREG-01 AC7): orienta a palavra
 * exata sem afirmar que as mensagens pararam (AC10).
 */
const OPT_OUT_REGISTRATION_FAILED =
  "Não consegui registrar seu pedido agora. Para encerrar, responda com a palavra sair, sozinha.";

/**
 * @param {unknown} value
 * @returns {value is string}
 */
function isNonEmptyText(value) {
  return typeof value === "string" && value.trim() !== "";
}

/**
 * Última mensagem de autoria do agente na sessão corrente.
 *
 * `loaded` é a saída de `Chat Memory Manager: carregar sessão`
 * (`{ messages, messagesCount }`, formato registrado na T1, execução 2598):
 * cada elemento agrupa mensagens consecutivas por autoria; `ai` string é a
 * fala do agente, `ai: []` é uma chamada de tool sem texto (ignorada),
 * `human` é o lead e `tool` é o resultado de tool.
 *
 * `seeded` são os itens de `Code: selecionar mensagens de semeadura`:
 * `{ type: 'user'|'ai', message, nadaParaSemear: false }` ou o sentinela
 * `{ nadaParaSemear: true }`.
 *
 * Precedência: uma carga não vazia É a sessão corrente, e a semeadura é
 * ignorada (mesmo que a carga não tenha fala do agente). A semeadura só vale
 * quando a carga veio vazia. Ausente (undefined/null) conta como vazio.
 * Sessão vazia → `null` (é o caso do "sim" depois do corte de 12h).
 *
 * @param {{ loaded?: { messages?: unknown } | null, seeded?: unknown }} input
 * @returns {string | null}
 */
function lastAgentMessage({ loaded, seeded } = {}) {
  const messages = Array.isArray(loaded?.messages) ? loaded.messages : [];
  if (messages.length > 0) {
    for (let i = messages.length - 1; i >= 0; i--) {
      const ai = messages[i]?.ai;
      if (isNonEmptyText(ai)) return ai;
    }
    return null;
  }

  const items = Array.isArray(seeded) ? seeded : [];
  for (let i = items.length - 1; i >= 0; i--) {
    const item = items[i];
    if (item?.nadaParaSemear === true) continue;
    if (item?.type === "ai" && isNonEmptyText(item.message)) return item.message;
  }
  return null;
}

/**
 * Texto que o classificador lê (OPTREG-01 AC2: só a mensagem do turno e a
 * última mensagem enviada). `userMessage` aceita o texto pronto ou a lista de
 * textos do buffer do turno, unida por quebra de linha, como o `userMessage`
 * do agente (`principal.ts`, `buffer.map((m) => m.text).join('\n')`).
 *
 * @param {{ lastAgentMessage?: string | null, userMessage?: string | string[] | null }} input
 * @returns {string}
 */
function buildClassifierInput({ lastAgentMessage, userMessage } = {}) {
  const last = isNonEmptyText(lastAgentMessage) ? lastAgentMessage : "(nenhuma)";
  const text = Array.isArray(userMessage) ? userMessage.join("\n") : (userMessage ?? "");
  return `Última mensagem enviada ao lead: ${last}\nMensagem do lead: ${text}`;
}

/**
 * Minúsculas, sem acento, espaços colapsados. A lista do buffer vira um texto
 * só, unido por quebra de linha, como em `buildClassifierInput`.
 *
 * @param {string | string[] | null | undefined} userMessage
 * @returns {string}
 */
function normalizeUserMessage(userMessage) {
  const text = Array.isArray(userMessage) ? userMessage.join("\n") : (userMessage ?? "");
  return String(text)
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

/** "parar/para/pare/parem de [me/nos] mandar|enviar <objeto>". */
const STOP_SENDING_OBJECT = /\b(?:parar|para|pare|parem) de (?:(?:me|nos) )?(?:mandar|enviar) \S/;

/** Menção ao contato em si: com qualquer uma delas, o pedido não é só de conteúdo. */
const CONTACT_MENTION = /mensag|msg|contat|lista|descadastr|nada|whatsapp/;

/** "mensagem de voz" é formato (como áudio), não o contato em si. */
const VOICE_MESSAGE = /mensage(?:m|ns) de (?:voz|audio)/g;

/**
 * Pedido para parar de mandar só um conteúdo, formato ou filtro de busca
 * ("para de mandar casa, eu quero apartamento"), sem menção ao contato em si.
 * Trava determinística depois do classificador (T12d, decisão D3): a medição
 * v3 deixou falsos positivos aleatórios exatamente nesse formato.
 *
 * @param {string | string[] | null | undefined} userMessage
 * @returns {boolean}
 */
function isContentOnlyStop(userMessage) {
  const text = normalizeUserMessage(userMessage);
  if (!STOP_SENDING_OBJECT.test(text)) return false;
  return !CONTACT_MENTION.test(text.replace(VOICE_MESSAGE, ""));
}

/**
 * Categoria final do turno: `explicita` com pedido só de conteúdo vira
 * `ambigua` (o agente pergunta em vez de descadastrar). Qualquer outra
 * categoria passa inalterada.
 *
 * @param {{ categoria?: string, userMessage?: string | string[] | null }} input
 * @returns {string | undefined}
 */
function refineOptOutCategory({ categoria, userMessage } = {}) {
  if (categoria === "explicita" && isContentOnlyStop(userMessage)) return "ambigua";
  return categoria;
}

const ctx = $('Code: gate').first().json;
const mensagens = [OPT_OUT_CONFIRMATION];
return [{ json: { mensagens, waId: ctx.waId, phoneNumberId: ctx.phoneNumberId, tenantSlug: ctx.tenantSlug, leadId: ctx.id, fase: 'encerrada' } }];

const ctx = $('Code: gate').first().json;
const mensagens = ['Recebi seu arquivo, mas por aqui eu sigo só por mensagens de texto — pode me contar em palavras o que você gostaria de saber?'];
return [{ json: { mensagens, waId: ctx.waId, phoneNumberId: ctx.phoneNumberId, tenantSlug: ctx.tenantSlug, leadId: ctx.id, fase: ctx.fase || 'qualificando' } }];

/**
 * Normalização do destinatário de envio no WhatsApp (nono dígito brasileiro).
 *
 * PROBLEMA REAL (execução 354 de `crivo-agente-principal`, confirmado contra
 * duas fontes): o webhook da Meta entrega o contato em `wa_id` no formato
 * LEGADO, sem o nono dígito — `553499532444` (12 dígitos) — enquanto a Cloud
 * API só aceita como destinatário o número atual, com o 9 — `5534999532444`
 * (13 dígitos, o mesmo valor que o painel da Meta usa no campo `to` do curl
 * de exemplo). Enviar o `wa_id` cru resulta em erro 131030 ("Recipient phone
 * number not in allowed list") — ou seja, TODA resposta do agente a um lead
 * brasileiro falha, não só a do número de teste.
 *
 * ESCOPO DELIBERADO: esta função normaliza SÓ o destinatário do envio. O
 * `wa_id` cru continua sendo a chave das Data Tables (`conversa_estado`,
 * `agenda_envios`) e o `externalId` do lead no CRM — mudar essas chaves
 * quebraria o casamento com os eventos recebidos da Meta, que sempre chegam
 * no formato legado.
 *
 * Função pura, sem I/O, sem dependências — roda dentro de um Code node do
 * n8n (sandbox: sem `require`, sem rede).
 */

// Marca do país no formato E.164 sem o "+" (é como o `wa_id` chega da Meta).
const BRAZIL_COUNTRY_CODE = "55";

// Comprimentos brasileiros: 55 + DDD(2) + 8 (formato legado, pré-nono-dígito)
// e 55 + DDD(2) + 9 (formato atual). Só o primeiro precisa de conserto.
const BR_LEGACY_LENGTH = 12;
const BR_DDD_END_INDEX = 4; // fim de "55" + DDD

// Discriminador celular x fixo (Anatel — Plano de Numeração Brasileiro,
// cartilha do nono dígito): o 9 foi acrescentado SÓ aos números do Serviço
// Móvel Pessoal, que no formato legado de 8 dígitos começavam com 6, 7, 8 ou
// 9; a telefonia fixa também tem 8 dígitos, mas começa com 2, 3, 4 ou 5 e
// NUNCA recebeu o nono dígito. Sem esse discriminador, um fixo de 8 dígitos
// gravado como contato viraria um celular inexistente de 9 dígitos.
const BR_MOBILE_LOCAL_PREFIX = /^[6-9]/;

const NON_DIGIT_PATTERN = /\D/g;

/**
 * Converte um `wa_id` da Meta no MSISDN aceito pela Cloud API como
 * destinatário de envio.
 *
 * Regras (nesta ordem):
 * 1. Entrada não-string ou sem nenhum dígito (null/undefined/""/lixo) → `""`.
 *    Devolver string vazia (em vez do valor cru) evita que o nó de envio
 *    mande literalmente "undefined" para a Meta; o envio falha de forma
 *    explícita, que é o comportamento defensivo dos módulos vizinhos
 *    (`normalizeEvent` → null, `detectOptOut` → false).
 * 2. Caracteres não numéricos (`+`, espaço, hífen) são descartados — o
 *    `wa_id` da Meta é sempre só dígitos, mas o valor pode chegar de uma
 *    Data Table preenchida à mão.
 * 3. Número brasileiro (prefixo `55`) no formato legado (12 dígitos) cujo
 *    número local começa com 6-9 (celular) → insere `9` depois do DDD.
 * 4. Qualquer outro caso — brasileiro já com 13 dígitos, fixo brasileiro de
 *    8 dígitos locais, número de outro país, comprimento inesperado — volta
 *    inalterado. Nenhuma regra de outro país é inventada aqui.
 *
 * Idempotente por construção: o resultado da regra 3 tem 13 dígitos e cai na
 * regra 4 numa segunda aplicação.
 *
 * @param {unknown} waId - `wa_id` do contato no evento da Meta
 * @returns {string} MSISDN pronto para `recipientPhoneNumber`
 */
function toWhatsAppMsisdn(waId) {
  if (typeof waId !== "string") return "";

  const digits = waId.replace(NON_DIGIT_PATTERN, "");
  if (digits === "") return "";

  if (!digits.startsWith(BRAZIL_COUNTRY_CODE)) return digits;
  if (digits.length !== BR_LEGACY_LENGTH) return digits;

  const ddd = digits.slice(0, BR_DDD_END_INDEX);
  const local = digits.slice(BR_DDD_END_INDEX);
  if (!BR_MOBILE_LOCAL_PREFIX.test(local)) return digits;

  return `${ddd}9${local}`;
}

const ctx = $input.first().json;
return [{ json: { ...ctx, recipientMsisdn: toWhatsAppMsisdn(ctx.waId) } }];

/**
 * Expiração de sessão e semeadura da memória (design.md — n8n/src/session.mjs;
 * spec.md MEM-02, MEM-03). Funções puras, sem I/O, sem dependências — rodam
 * dentro de um Code node do n8n. Absorve o corte de sessão de `history.mjs`
 * (o teto de 20 mensagens é removido — AD-019: sem teto de política, só a
 * salvaguarda alta de 50).
 */

const DEFAULT_SESSION_GAP_HOURS = 12;
const DEFAULT_MAX_SEED_MESSAGES = 50;

/**
 * @typedef {{sender: "lead"|"agente"|"humano", content: string, sentAt: string, authorName?: string|null}} HistoryMessage
 */

/**
 * @typedef {{type: "ai"|"user"|"system", message: string}} SeedMemoryItem
 */

const UNKNOWN_AUTHOR = "alguém da equipe";

/**
 * Decide se a sessão expirou: o intervalo entre a mensagem atual (`now`) e a
 * última mensagem RECEBIDA da sessão (`lastInboundAt`) é maior que
 * `gapHours` (spec.md — MEM-02 AC3). `lastInboundAt` nulo significa
 * conversa nova, sem sessão nenhuma a purgar — nunca `true` (tasks.md — T3
 * Done-when). O limite é estritamente "maior que", não "maior ou igual"
 * (mesma convenção de `history.mjs`/`business-hours.mjs`): exatamente 12h de
 * intervalo NÃO expira a sessão.
 * @param {string | null | undefined} lastInboundAt
 * @param {string} now
 * @param {number} [gapHours]
 * @returns {boolean}
 */
function isSessionExpired(lastInboundAt, now, gapHours = DEFAULT_SESSION_GAP_HOURS) {
  if (lastInboundAt === null || lastInboundAt === undefined || lastInboundAt === "") {
    return false;
  }

  const last = new Date(lastInboundAt).getTime();
  const current = new Date(now).getTime();
  if (Number.isNaN(last) || Number.isNaN(current)) return false;

  const gapMs = gapHours * 60 * 60 * 1000;
  return current - last > gapMs;
}

/**
 * Seleciona, dentre as mensagens do CRM, as que pertencem à sessão CORRENTE
 * para semear a memória em cold start (spec.md — MEM-03 AC5). Varre de trás
 * para frente comparando intervalos consecutivos — incluindo `now` como um
 * ponto de corte adicional ao final da lista: se já existe um intervalo
 * maior que `sessionGapHours` entre a última mensagem real e o instante
 * atual, nenhuma mensagem antiga é trazida (a sessão já teria sido purgada
 * por `isSessionExpired` antes deste passo — este cálculo apenas não
 * pressupõe essa ordem). Depois do corte de sessão, aplica só a salvaguarda
 * de `maxMessages` (default 50) — NUNCA o antigo teto de 20 (AD-019).
 * @param {HistoryMessage[] | null | undefined} messages - ordem cronológica crescente (mais antiga primeiro)
 * @param {string} now
 * @param {{maxMessages?: number, sessionGapHours?: number}} [options]
 * @returns {HistoryMessage[]}
 */
function selectSeedMessages(
  messages,
  now,
  { maxMessages = DEFAULT_MAX_SEED_MESSAGES, sessionGapHours = DEFAULT_SESSION_GAP_HOURS } = {}
) {
  const list = Array.isArray(messages) ? messages : [];
  if (list.length === 0) return [];

  const gapMs = sessionGapHours * 60 * 60 * 1000;
  const nowMs = new Date(now).getTime();

  let sessionStart = 0;
  let previousMs = nowMs;
  for (let i = list.length - 1; i >= 0; i--) {
    const currentMs = new Date(list[i].sentAt).getTime();
    if (previousMs - currentMs > gapMs) {
      sessionStart = i + 1;
      break;
    }
    previousMs = currentMs;
  }

  const session = list.slice(sessionStart);
  return session.length > maxMessages ? session.slice(session.length - maxMessages) : session;
}

/**
 * Converte uma mensagem do CRM no item que a semeadura insere na memória do
 * agente (lote-14 — DEVOLVER-01 AC5, AC6). `agente` → `ai`; `lead` → `user`;
 * `humano` → `system`, com a atribuição ao corretor (tipo confirmado na T1:
 * o `memoryManager` aceita `system` no meio da sessão e o modelo usa o fato).
 * A fala humana nunca entra como `user`: o modelo a leria como fala do lead.
 * Remetente desconhecido é descartado (`null`).
 * @param {Partial<HistoryMessage> & {sender?: unknown}} message
 * @returns {SeedMemoryItem | null}
 */
function toSeedMemoryItem(message) {
  const content = message.content;
  if (message.sender === "agente") return { type: "ai", message: content };
  if (message.sender === "lead") return { type: "user", message: content };
  if (message.sender === "humano") {
    const name = typeof message.authorName === "string" ? message.authorName.trim() : "";
    const author = name === "" ? UNKNOWN_AUTHOR : name;
    return {
      type: "system",
      message: `Mensagem enviada ao lead por ${author}, da equipe da imobiliária: ${content}`,
