const precisaFallback = !calledResponder && respostaFallback.length > 0;
return [{ json: { tenantSlug: ctx.tenantSlug, waId: ctx.waId, fase, turnoSemResposta: !calledResponder, autoSaved, respostaFallback, precisaFallback } }];

const humanMessage = $('Code: montar system message e marcar campo perguntado').first().json.userMessage;
const agentTurn = $('AI Agent').first().json;
const steps = Array.isArray(agentTurn.intermediateSteps) ? agentTurn.intermediateSteps : [];
const agentMessages = steps
  .filter((s) => s && s.action && s.action.tool === 'responder_lead')
  .map((s) => s.action.toolInput && s.action.toolInput.mensagem)
